import os
import json
import glob
import re
from google import genai
from google.genai import types

def get_failed_allure_context(results_dir="report/allure-results"):
    """Scans Allure raw results directory to extract the dynamic page and error metrics."""
    if not os.path.exists(results_dir):
        print(f"❌ Allure results directory not found at: {results_dir}")
        return None, None, None

    # Search for all test case result files generated by allure-playwright
    result_files = glob.glob(os.path.join(results_dir, "*-result.json"))
    
    for file_path in result_files:
        with open(file_path, "r", encoding="utf-8") as f:
            test_data = json.load(f)
        
        # Identify if this specific test execution failed
        if test_data.get("status") in ["failed", "broken"]:
            # Extract the raw execution error message from Allure
            status_details = test_data.get("statusDetails", {})
            error_message = status_details.get("message", "") + "\n" + status_details.get("trace", "")
            
            # Look for the test specification file location
            spec_file = "Unknown"
            for label in test_data.get("labels", []):
                if label.get("name") == "suite":
                    spec_file = label.get("value", "")

            # DYNAMIC EXTRACTION LOGIC:
            # Parse the error trace to see which Page Object file under /pages/ crashed
            page_match = re.search(r"pages/[\w-]+\.ts", error_message)
            
            if page_match:
                dynamic_page_path = page_match.group(0)
            else:
                # Fallback Strategy: Infer Page name from spec name (e.g. login.spec.ts -> pages/LoginPage.ts)
                base_name = os.path.basename(spec_file).replace(".spec.ts", "")
                dynamic_page_path = f"pages/{base_name}.page.ts"

            return spec_file, dynamic_page_path, error_message

    return None, None, None

def run_free_allure_repair():
    spec_file, target_page_path, error_message = get_failed_allure_context()
    
    if not target_page_path:
        print("✅ No test failures found in Allure results.")
        return

    if not os.path.exists(target_page_path):
        print(f"❌ Target page file does not exist locally: {target_page_path}")
        return

    print(f"🎯 Dynamic Target Found via Allure -> {target_page_path}")

    with open(target_page_path, "r", encoding="utf-8") as f:
        original_page_code = f.read()

    # Call your free Gemini API instance
    client = genai.Client(api_key=os.environ.get("GEMINI_API_KEY"))

    system_instruction = (
        "You are an expert Playwright automation agent. Your sole purpose is fixing flaky selectors "
        "and synchronization issues within Page Object files inside the /pages directory. "
        "You must respond ONLY with the raw updated TypeScript code. Do not include markdown wraps or ``` blocks."
    )

    prompt = f"""
    The test suite failed on an element interaction. Analyze the details below and repair the Page Object class.

    ALLURE FAILURE LOGS:
    {error_message}

    CURRENT PAGE OBJECT CODE:
    {original_page_code}

    BOUNDED RULES:
    1. Look for the property causing the timeout in the constructor (likely a CSS id like '#lastName').
    2. If the #id has changed or seems dynamic, optimize it to use a modern Playwright locator framework.
    3. NEVER add raw 'page.waitForTimeout()' delays.
    4. Provide the COMPLETE updated code for {target_page_path}.
    """

    print("🤖 Invoking Gemini Flash (Free Tier) to heal code stack...")
    response = client.models.generate_content(
        model='gemini-2.5-flash',
        contents=prompt,
        config=types.GenerateContentConfig(
            system_instruction=system_instruction,
            temperature=0.1
        )
    )

    # Clean markdown fences if the model wraps it
    cleaned_code = re.sub(r'^```ts\s*|^```typescript\s*|^```\s*|```$', '', response.text.strip(), flags=re.MULTILINE)

    with open(target_page_path, "w", encoding="utf-8") as f:
        f.write(cleaned_code)
    
    print(f"✅ Page Object at '{target_page_path}' successfully repaired using Allure context.")

if __name__ == "__main__":
    run_free_allure_repair()
